def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 502.874162065159  # OPT_PARAM: {"initial": 502.874162065159, "min": 400, "max": 700, "type": "float"}
    safety_stock = 115.11238828186528  # OPT_PARAM: {"initial": 115.11238828186528, "min": 50, "max": 180, "type": "float"}
    order_cap = 88.55933697428695  # OPT_PARAM: {"initial": 88.55933697428695, "min": 80, "max": 300, "type": "float"}
    pipeline_weight = 0.3  # OPT_PARAM: {"initial": 0.3, "min": 0.3, "max": 1.2, "type": "float"}
    demand_buffer = 0.9793450380640744  # OPT_PARAM: {"initial": 0.9793450380640744, "min": 0.8, "max": 1.8, "type": "float"}
    recent_weight = 0.9489852214060467  # OPT_PARAM: {"initial": 0.9489852214060467, "min": 0.1, "max": 1.0, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Calculate demand estimate using weighted average of recent arrivals
    if len(pipeline_orders) > 0:
        # Give more weight to recent arrivals
        if len(pipeline_orders) >= 2:
            recent_avg = (pipeline_orders[0] * recent_weight + 
                         pipeline_orders[1] * (1 - recent_weight))
        else:
            recent_avg = pipeline_orders[0]
        demand_estimate = recent_avg * demand_buffer
    else:
        demand_estimate = 100.0

    # Adjust base stock based on pipeline coverage
    pipeline_total = sum(pipeline_orders)
    if pipeline_total > 0:
        # More aggressive adjustment when pipeline is low
        expected_pipeline = demand_estimate * len(pipeline_orders)
        if pipeline_total < expected_pipeline * 0.8:
            adjusted_base = base_stock * (1 + pipeline_weight)
        elif pipeline_total > expected_pipeline * 1.2:
            adjusted_base = base_stock * (1 - pipeline_weight * 0.5)
        else:
            adjusted_base = base_stock
    else:
        adjusted_base = base_stock

    # Calculate target order
    target_order = adjusted_base - inventory_position

    # Add safety stock based on immediate coverage
    if len(pipeline_orders) > 0:
        immediate_coverage = on_hand_inventory + pipeline_orders[0]
        if immediate_coverage < demand_estimate * 1.5:
            target_order += safety_stock

    # Apply order cap and ensure non-negative
    order_amount = max(0, min(target_order, order_cap))

    # Round to integer
    return order_amount
